function bandage(s,p,t,rng,personal=false){const clinic=p.location==='clinic',kit=p.items.bandage>0;if(kit)p.items.bandage--;let gain=0;const terms=[];if(p.location==='clinic')terms.push({label:'진료소 처치대',value:2});if(s.turn===2)terms.push({label:'밤의 어둠',value:-2});
 const r=check(p,'medical',rng,{label:'지혈',dc:s.cfg.medicalDifficulty,terms,edge:kit?1:-1});r.edgeReason=clinic?'진료소 처치대에서 붕대를 사용':kit?'붕대를 사용해 안정적으로 압박':'붕대 없이 즉석 처치';if(r.success){t.bleeding=false;treatMarks(t);/* 2026-11-24 진료소 고침(사용자): 진료소에서나 의사가 지혈하면 체력도 오름 */if(clinic||p.role==='doctor'){const add=s.cfg?.clinicBandageHeal??config.clinicBandageHeal;gain=Math.max(0,Math.min(maxHp(t),t.hp+add)-t.hp);t.hp+=gain;}}noteStatus(s,personal?[p.id]:localIds(s,p),t,{bleeding:!!t.bleeding});
 emit(s,personal?[p.id]:localIds(s,p),'check',`${pp(p.name,'이','가')} ${t.name}의 상처를 압박했습니다. ${r.success?'출혈이 멎었습니다.':'압박이 충분하지 않아 피가 계속 배어 나옵니다.'} ${gain?(clinic?'진료소':'의사')+'의 처치라 체력이 '+gain+' 올라 '+t.hp+'입니다.':'체력은 '+t.hp+'로, 회복되지 않습니다.'}`,{roll:r});
}
/* 2026-11-24 진료소 고침(사용자): 간호사 치료를 받을 수 없는 까닭(없으면 null) */function nurseProblem(s,p){const st=s.scenario?.continuation,n=st?.npcs?.nurse,price=s.cfg?.nursePrice??config.nursePrice;if(p.location!=='clinic')return '진료소에서만 간호사에게 치료받을 수 있습니다.';if(n&&(n.hp<=0||n.location!=='clinic'))return '간호사가 진료소에 없습니다.';if(st&&!(st.medStock>0))return '진료소 치료제가 모두 떨어졌습니다.';if((p.money||0)<price)return '간호사 치료에는 소지금 '+price+'이 듭니다.';if(p.hp>=maxHp(p)&&!p.bleeding)return '치료받을 상처가 없습니다.';return null;}
function nurseCare(s,p){const why=nurseProblem(s,p);if(why){narrate(s,p.id,'간호사에게 치료받지 못했습니다. '+why);return;}const st=s.scenario?.continuation,price=s.cfg?.nursePrice??config.nursePrice,before=p.hp;p.money-=price;if(st)st.medStock--;p.hp=Math.min(maxHp(p),p.hp+(s.cfg?.nurseHeal??config.nurseHeal));p.bleeding=false;treatMarks(p);
 emit(s,localIds(s,p),'story',pp(p.name,'이','가')+' 진료소에서 간호사에게 치료받았습니다.');narrate(s,p.id,'간호사에게 치료받았습니다. 소지금 '+price+' 지출 · 남은 소지금 '+p.money+' · 체력 '+before+' → '+p.hp+', 출혈 멎음.'+(st?' 진료소 치료제 '+st.medStock+'개 남음.':''));}
function recruit(s,p,t,a,rng){if(root.NoirScenarios)return root.NoirScenarios.recruit(s,p,t,a,rng);const r=check(p,'persuade',rng,{label:'영입 설득',dc:16});p.hidden=false;p.spotted=[];emit(s,[p.id,t.id],'check',`${pp(p.name,'이','가')} ${t.name}에게 같은 편으로 합류할 것을 제안했습니다. ${r.success?'제안이 전달됐습니다. 상대가 직접 수락해야 진영이 바뀝니다.':'상대를 설득하지 못했습니다. 진영은 바뀌지 않았습니다.'}`,{roll:r});learn(s,t.id,`${pp(p.name,'이','가')} 마피아 합류를 제안했다.`,p.id,'직접 받은 제안','claim');if(r.success)s.offers.push({id:'o'+(++s.serial),kind:'recruit',from:p.id,to:t.id,terms:String(a.reason||'함께 살아남기').slice(0,300),done:false});}
/* 2026-11-25 사용자 "찾아가기+도움 청하기": 쓰러진 사람은 한 번 도움을 청한다. 같은 장소 사람은 누구인지와 어디인지, 다른 곳 사람은 어느 쪽인지만 듣는다 */function callHelp(s,id){const p=find(s,id);if(!p||!p.downed)return '쓰러져 있을 때만 도움을 청할 수 있습니다.';if(p.downed.called)return '도움은 이미 한 번 청했습니다.';p.downed.called=true;const pl=places[p.location].name,house=p.location==='home';narrate(s,id,'있는 힘을 다해 도움을 청했습니다.',{tag:'내 행동'});metric(s,'callHelp',p,{place:p.location});for(const o of alive(s).filter(o=>o.id!==id)){const near=o.location===p.location;emit(s,[o.id],'story',near?(house?'주택가 '+p.name+'의 집에서 도움을 청하는 신음 소리가 들립니다.':pp(p.name,'이','가')+' 쓰러진 채 도움을 청하는 소리가 들립니다.'):pl+' 쪽에서 누군가 도움을 청하는 소리가 들립니다.',{tag:'들은 것'});if(near)learn(s,o.id,label(s)+' '+(house?'주택가 '+p.name+'의 집':pl)+'에서 '+pp(p.name,'이','가')+' 도움을 청하는 소리를 들었다.',p.id,'직접 들음','observed');}return null;}
function caseDay(s){return s.day+(s.turn===2?1:0);}
function closeCases(s,selected){for(const c of s.cases.filter(c=>c.day===s.day&&!c.closed&&c.id!==selected)){c.closed=true;c.status=c.asked&&c.support.filter(id=>find(s,id)?.hp>0).length<Math.ceil(alive(s).length/3)?'동의가 모자라 열리지 않음':'오늘 다른 재판이 먼저라 열리지 않음';/* 2026-11-25 자율 순환: 동의를 받지 않은 신청은 다른 재판이 먼저라 닫힘 */const to=s.players.filter(p=>p.id===c.by||p.knownCases?.includes(c.id)||p.location==='hall').map(p=>p.id);emit(s,to,'notice',(find(s,c.by)?.name||c.byName||'누군가')+' → '+find(s,c.target).name+' 재판 신청: '+c.status+'.');}}
function create(seats,rng,settings={}){
 const ids=seats.map(p=>p.id),shuffled=[...ids].sort(()=>0);for(let i=shuffled.length-1;i>0;i--){const j=die(rng,i+1)-1;[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}
 const mafiaCount=Math.max(1,Math.floor(ids.length/3)),gang=new Set(shuffled.slice(0,mafiaCount)),bySeat={};
 for(const team of ['mafia','town']){const members=shuffled.filter(id=>gang.has(id)===(team==='mafia')),jobs=rolePools[team].slice(0,members.length);if(jobs.length!==members.length)throw new Error('지원하는 인원 범위를 벗어났습니다.');for(let i=jobs.length-1;i>0;i--){const j=die(rng,i+1)-1;[jobs[i],jobs[j]]=[jobs[j],jobs[i]];}members.forEach((id,i)=>bySeat[id]=jobs[i]);}
 const s={cfg:{...config,...settings},day:1,turn:0,stage:'small',epoch:1,players:seats.map((p,i)=>{const job=bySeat[p.id],r=roles[job],team=gang.has(p.id)?'mafia':'town';return {...p,role:job,team,money:team==='mafia'?(settings.mafiaMoney??config.mafiaMoney):(settings.townMoney??config.townMoney),hp:10,bleeding:false,hidden:false,location:'hall',stats:{...r.stats,fight:team==='mafia'?Math.max(7,r.stats.fight):r.stats.fight},items:{...r.items},used:{big:false,small:false},defense:'dodge',known:[],photos:[],guesses:{},will:'',filedDay:0,jailDay:0,jailEpoch:0};}),newspapers:[],feed:[],events:[],cases:[],offers:[],plans:{},ready:[],reactions:{},serial:0,ai:{mode:'off',answered:0,fallback:0,pending:0},startedAt:Date.now(),trial:null,result:null};
 s.composition=['mafia','town','neutral'].map(team=>({team,roles:Object.entries(roles).map(([role])=>({role,count:s.players.filter(p=>p.team===team&&p.role===role).length})).filter(x=>x.count)}));
 if(root.NoirScenarios)root.NoirScenarios.start(s,rng);else emit(s,ids,'story','마피아의 습격에 주민들이 회관에 모여 투표로 범인을 가려내기로 했습니다. 일곱째 날 밤이 지나면 외부 경찰과 판사가 도착합니다.');return s;
}
function emit(s,to,kind,text,extra={}){if(extra&&extra.roll)rollMetric(s,extra.roll);if(s.aliases&&['story','environment','check'].includes(kind)&&s.players.some(c=>c.faceCover)){const base=korean(s,text),g=new Map();for(const id of [...new Set(to)]){const t=maskText(s,id,base).text;if(!g.has(t))g.set(t,[]);g.get(t).push(id);}if(g.size>1||!g.has(base)){let last=null;for(const [t,ids] of g)last=emitRaw(s,ids,kind,t,extra)||last;return last;}}return emitRaw(s,to,kind,text,extra);}
function emitRaw(s,to,kind,text,extra={}){if(s.actionContext&&!['speech','environment','death'].includes(kind))extra={actionRecord:true,...extra};text=korean(s,text);if(kind==='environment'||kind==='story'){s.envSent??={};to=to.filter(id=>{const k=s.epoch+'|'+id+'|'+text;if(s.envSent[k])return false;s.envSent[k]=1;return true;});if(!to.length)return null;}const locations=[...new Set(to.map(id=>find(s,id)?.location).filter(Boolean))];const e={place:locations.length===1?locations[0]:null,i:++s.serial,to:[...new Set(to)],kind,text,time:label(s),epoch:s.epoch,...extra};s.feed.push(e);return e;}
// 이름 뒤의 조사를 받침에 맞춘다. 플레이어 이름과 NPC 이름 모두에 적용한다.
// 낱말 끝 받침에 맞춰 조사를 붙인다. 예: pp('교회','을','를') → '교회를'
/* 낱말 끝 받침 번호(없음 0, ㄹ 8). 숫자는 읽는 소리로(1 일, 2 이 …), 그 밖의 글자는 -1 */function tailOf(word){word=String(word);const ch=word[word.length-1]||'',c=ch.charCodeAt(0);if(c>=44032&&c<=55203)return (c-44032)%28;const d={'0':21,'1':8,'2':0,'3':16,'4':0,'5':0,'6':1,'7':8,'8':8,'9':0}[ch];return d===undefined?-1:d;}
function withRo(word){word=String(word);const t=tailOf(word);return word+(t>0&&t!==8?'으로':'로');}
function pp(word,a,b){word=String(word);return word+(tailOf(word)!==0?a:b);}
function korean(s,text){let t=String(text);const names=[...s.players.map(p=>p.name),'해먼드','도일','리스','간호사','광부','술집 주인','종지기','하숙집 주인',...Object.values(s.aliases||{}).map(n=>'변장한 사람 '+n)].filter(Boolean).sort((a,b)=>b.length-a.length);for(const name of names){const tail=tailOf(name)!==0;for(const [a,b] of [['이','가'],['을','를'],['은','는'],['과','와']])for(const used of [a,b])t=t.split(name+used+' ').join(name+(tail?a:b)+' ');}return t;}
function learn(s,id,text,about,source,kind='observed',event=null){text=korean(s,text);if(kind==='observed'||kind==='evidence'){const m=maskText(s,id,text,about);text=m.text;about=m.about;}const p=find(s,id);if(!p)return;const n={id:'k'+(++s.serial),text,about:about||null,source,kind,time:label(s),event};p.known.push(n);return n;}
/* 주택가는 낮에도 각자의 집이다. 같은 집에 있을 때만 서로 보인다 */function sameSpace(s,a,b){return a.location===b.location&&(a.location!=='home'||(a.alley||b.alley?a.alley===b.alley:(a.houseId||a.id)===(b.houseId||b.id)));}
// 변장: 같은 편이거나 간파한 사람에게는 통하지 않는다. 간파는 사람마다 한 턴에 한 번 정해진다(주사위 + 관찰 ≥ 9 + 변장한 사람의 은신).
function hashN(str){let h=2166136261;for(const c of String(str)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return Math.abs(h);}
function seesThrough(s,viewer,p){if(!viewer||viewer.id===p.id||viewer.team==='mafia'&&p.team==='mafia')return true;const roll=1+hashN(viewer.id+'|'+p.id+'|'+s.epoch)%10;return roll+(viewer.stats?.observe||0)>=9+(p.stats?.agility||0);}
/* 변장(얼굴 가리기, 2026-11-19 사용자: 누군지 모르게 입거나 꾸미는 것은 누구나 쉽게 한다; "변장한 사람 1 변장한 사람 2 이런식으로"; "행동으로 먼저 변장을 했으면 그사람이 1이 되고"; "대놓고 변장하면 누가 변장했는지 보이겠죠"; 숨은 게 아니니 행동 대상이 된다).
   처음 변장한 차례로 번호가 붙고 그 판 내내 같다. 벗거나 붙잡힐 때까지 이어진다. 변장하거나 벗는 것을 본 사람과 같은 편은 누군지 안다(aliasKnown). 모르는 사람에게는 'v번호'라는 따로 된 사람으로 보인다 */
function aliasNo(s,p){return s.aliases?.[p?.id]||0;}
function aliasOf(s,p){const n=aliasNo(s,p);return n?{id:'v'+n,name:'변장한 사람 '+n,faceless:true,alias:n}:null;}
function knowsAlias(viewer,p,n){return viewer?.aliasKnown?.[n]?.id===p.id;}
function aliasPerson(s,id){const m=typeof id==='string'&&/^v([0-9]+)$/.exec(id);if(!m||!s.aliases)return undefined;const pid=Object.keys(s.aliases).find(k=>s.aliases[k]===+m[1]);const p=pid&&s.players.find(q=>q.id===pid);return p&&p.faceCover?p:undefined;}
function learnAlias(s,ids,p){const n=aliasNo(s,p);if(!n)return;for(const id of ids){const o=s.players.find(q=>q.id===id);if(o&&o.id!==p.id)(o.aliasKnown??={})[n]={id:p.id,name:p.name};}}
/* 지표: 분석용으로 판 기록에 남는 숫자(화면과 AI에는 가지 않는다) */function metric(s,kind,p,extra={}){(s.metrics??=[]).push({day:s.day,turn:s.turn,...(p?{actor:p.id,role:p.role,team:p.team,bot:!!p.bot}:{}),...extra,kind});}
/* 행동 하나를 숫자로 남길 모양: 무엇을, 어디서, 누구에게, 얼굴을 가렸는지, 같은 자리에 몇 명이 있었는지 */function actInfo(s,p,a,slot){const t=a.target?find(s,a.target):null;return {slot,type:a.type,verb:a.verb||null,sceneKey:a.sceneKey||null,place:p.location,targetTeam:t?.team||null,targetRole:t?.role||null,npc:a.npc||null,masked:!!p.faceCover,hidden:!!p.hidden,others:alive(s).filter(o=>o.id!==p.id&&!o.masked&&sameSpace(s,p,o)).length};}
/* 판정 하나를 한 번만 남긴다(같은 판정을 여러 사람에게 보여 줘도 한 번) */const ROLLED=new WeakSet();function rollMetric(s,r){if(!s||!r||typeof r!=='object'||ROLLED.has(r))return;ROLLED.add(r);const one=x=>x&&{label:x.label||null,statKey:x.statKey||null,stat:x.stat??null,roll:x.roll??null,total:x.total??null,difficulty:x.difficulty??null,success:x.success??null};const who=r.who||r.actor?.who;metric(s,'roll',who?find(s,who):null,r.kind==='opposed'?{opposed:true,label:r.actor?.label||null,a:one(r.actor),b:one(r.opponent),success:!!r.success,tie:!!r.tie}:one(r));}
function realTarget(s,a){if(!a||!a.target)return a;const t=find(s,a.target);return t&&t.id!==a.target?{...a,target:t.id}:a;}
/* 가리개가 벗겨진다: 그 자리에서 본 사람은 누군지 알게 된다 */function unmask(s,p,text){if(!p||!p.faceCover)return [];const n=aliasNo(s,p);p.faceCover=null;if(!n)return [];const ids=alive(s).filter(o=>o.id!==p.id&&visible(s,o,p)).map(o=>o.id),fresh=ids.filter(id=>{const o=find(s,id);return !knowsAlias(o,p,n)&&!(o.team==='mafia'&&p.team==='mafia');});learnAlias(s,ids,p);if(fresh.length){emit(s,fresh,'story',text||('변장한 사람 '+n+'의 얼굴이 드러납니다. '+p.name+'입니다.'));for(const id of fresh)learn(s,id,'변장한 사람 '+n+'은 '+pp(p.name,'이었','였')+'다.',p.id,'직접 목격','observed');}return fresh;}
/* 모르는 사람에게 가는 글에서는 같은 자리에 있는 변장한 사람의 이름을 번호로 바꾼다('○○의 집'은 집 이름이라 그대로). 재판 중에는 바꾸지 않는다 */function maskText(s,vid,text,about){if(!s.aliases||['trial','vote','verdict','consent'].includes(s.stage))return {text,about};const v=s.players.find(q=>q.id===vid);if(!v)return {text,about};let t=String(text),ab=about;for(const c of s.players){if(!c.faceCover||c.id===vid||c.name.length<2||['사람','누군가'].includes(c.name)||!sameSpace(s,v,c))continue;const d=disguisedAs(s,v,c);if(!d||!d.faceless)continue;if(ab===c.id)ab=d.id;if(!t.includes(c.name))continue;t=t.split(c.name).reduce((acc,part,i)=>i===0?part:acc+(part.startsWith('의 집')?c.name:d.name)+part,'');}return {text:t===String(text)?text:korean(s,t),about:ab};}
function disguisedAs(s,viewer,p){if(p&&p.faceCover&&viewer&&viewer.id!==p.id&&!(viewer.team==='mafia'&&p.team==='mafia')){const a=aliasOf(s,p);if(a&&!knowsAlias(viewer,p,a.alias))return a;}const d=p?.disguise;if(!d||d.epoch!==s.epoch||d.broken)return null;const t=find(s,d.as);if(!t||t.hp<=0)return null;return seesThrough(s,viewer,p)?null:t;}
function nameFor(s,viewer,p){return disguisedAs(s,viewer,p)?.name||p.name;}
function idFor(s,viewer,p){const d=disguisedAs(s,viewer,p);return d?d.id:p.id;}
// 진짜 그 사람과 같은 자리에 서면 변장이 들통난다.
function checkDisguises(s){for(const p of alive(s)){const d=p.disguise;if(!d||d.epoch!==s.epoch||d.broken)continue;const t=find(s,d.as);if(t&&t.hp>0&&sameSpace(s,p,t)){d.broken=true;const ids=localIds(s,p).filter(x=>x!==p.id);emit(s,ids,'story',`${pp(t.name,'이','가')} 둘입니다. 가까이서 보니 한 사람은 ${pp(p.name,'이었','였')}습니다. ${t.name}처럼 꾸미고 있었습니다.`);for(const x of ids)learn(s,x,`${pp(p.name,'이','가')} ${t.name}처럼 변장하고 있었다.`,p.id,'직접 목격','observed');narrate(s,p.id,`진짜 ${t.name}과 마주쳐 변장이 들통났습니다.`);}}}
