function noise(s,src,text,kind='fight',skipNear=false){const range=HEAR[kind]??1,place=src.location,near=[],far=[];for(const o of alive(s)){if(sameSpace(s,o,src))continue;const d=distance(o.location,place);if(d>range)continue;(d===0?near:far).push(o.id);}if(near.length&&!skipNear)emit(s,near,'environment','가까운 집에서 '+text,{tag:'들림'});if(far.length)emit(s,far,'environment',places[place].direction+' 쪽에서 '+text,{tag:'들림'});}
